pub fn check_p61970_301_equipment_ap_con_complex_shacl_vs_converter_acdc_converter_dc_terminal_dc_conduc_etc(dataset: &CimDataset) -> Vec<Violation> {
    let mut ref_counts: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
    for src_mrid in dataset.by_type.get("ACDCConverterDCTerminal").into_iter().flatten() {
        if let Some(src) = dataset.entries.get(src_mrid)
            .and_then(|e| e.element.as_any().downcast_ref::<cimstructs::ACDCConverterDCTerminal>()) {
            if let Some(r) = &src.dc_conducting_equipment { *ref_counts.entry(r.mrid.as_str()).or_insert(0) += 1; }
        }
    }
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("VsConverter").into_iter().flatten() {
        let count = ref_counts.get(mrid.as_str()).copied().unwrap_or(0);
        if count < 2 {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "equ:ACDCConverter.DCTerminals-numberOfTerminals".to_string(),
                class:       "VsConverter".to_string(),
                property:    "C:301:EQ:ACDCConverter.DCTerminals:numberOfTerminals".to_string(),
                message:     "The converter does not have two terminals, i.e. two instances of ACDCConverterDCTerminal.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "C:301:EQ:ACDCConverter.DCTerminals:numberOfTerminals".to_string(),
                description: "A converter has two DC converter terminals.".to_string(),
            });
        }
    }
    violations
}

