pub fn check_p61970_301_equipment_ap_con_complex_shacl_cut_terminal_conducting_equipment_min_count(dataset: &CimDataset) -> Vec<Violation> {
    let mut ref_counts: std::collections::HashMap<&str, usize> = std::collections::HashMap::new();
    for src_mrid in dataset.by_type.get("Terminal").into_iter().flatten() {
        if let Some(src) = dataset.entries.get(src_mrid)
            .and_then(|e| e.element.as_any().downcast_ref::<cimstructs::Terminal>()) {
            if let Some(r) = &src.conducting_equipment { *ref_counts.entry(r.mrid.as_str()).or_insert(0) += 1; }
        }
    }
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("Cut").into_iter().flatten() {
        let count = ref_counts.get(mrid.as_str()).copied().unwrap_or(0);
        if count < 2 {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "equ:Switch-numberOfTerminals".to_string(),
                class:       "Cut".to_string(),
                property:    "C:301:EQ:Switch:numberOfTerminals".to_string(),
                message:     "The Switch (or subclass) does not have two terminals.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "C:301:EQ:Switch:numberOfTerminals".to_string(),
                description: "All switches are two terminal devices including grounding switches. ".to_string(),
            });
        }
    }
    violations
}

