pub fn check_p61970_301_equipment_ap_con_complex_shacl_grounding_impedance_terminal_conducting_equipment_etc_3(dataset: &CimDataset) -> Vec<Violation> {
    let mut has_value: std::collections::HashSet<&str> = std::collections::HashSet::new();
    for src_mrid in dataset.by_type.get("Terminal").into_iter().flatten() {
        let src = match dataset.entries.get(src_mrid)
            .and_then(|e| e.element.as_any().downcast_ref::<cimstructs::Terminal>()) {
            Some(o) => o, None => continue,
        };
        if src.phases.as_ref().map_or(true, |u| u.uri != "PhaseCode.N") { continue; }
        if let Some(r) = src.conducting_equipment.as_ref() { has_value.insert(r.mrid.trim_start_matches('#')); }
    }
    let mut violations = Vec::new();
    for mrid in dataset.by_type.get("GroundingImpedance").into_iter().flatten() {
        if !has_value.contains(mrid.as_str()) {
            violations.push(Violation {
                object_id:   mrid.clone(),
                rule_id:     "equ:Terminal.phases-phaseCodeN".to_string(),
                class:       "GroundingImpedance".to_string(),
                property:    "Terminal.ConductingEquipment".to_string(),
                message:     "Terminal.phases differs from PhaseCode.N for a grounding related class.".to_string(),
                severity:    "sh:Violation".to_string(),
                name:        "C:301:EQ:Terminal.phases:phaseCode".to_string(),
                description: "If the attribute is missing, three phases (ABC) shall be assumed, except for terminals of grounding classes (specializations of EarthFaultCompensator, GroundDisconnector, and Ground) which will be assumed to be N. Therefore, phase code ABCN is explicitly declared when needed, e.g. for star point grounding equipment.".to_string(),
            });
        }
    }
    violations
}

